example.code:
var persona = new Persona { Nombre = "Juan", Edad = 30 };

// Serializar a XElement
XElement xml = persona.Fx.Xml.ToXElement();

// Deserializar desde XElement
Persona restaurada = xml.Fx.Xml.FromXElement<Persona>();

// Serialización simple de objeto
var persona = new Persona { Nombre = "Juan", Edad = 30 };
XElement xml = persona.Fx.Xml.ToXElement();
// Resultado: <Persona><Nombre>Juan</Nombre><Edad>30</Edad></Persona>

// Guardar en archivo
xml.Save("persona.xml");

// Integrar en documento más grande
var documento = new XElement("Raiz",
    new XElement("Personas",
        persona.Fx.Xml.ToXElement()));

// Serializar tipo derivado como tipo base
Animal perro = new Perro { Nombre = "Buddy", Raza = "Labrador" };
XElement xml = perro.Fx.Xml.ToXElement(typeof(Animal));
// El resultado solo incluye propiedades de Animal

// Determinación de tipo en tiempo de ejecución
Type tipoSerializacion = ObtenerTipoSerializacion();
XElement xmlDinamico = obj.Fx.Xml.ToXElement(tipoSerializacion);

// Deserializar desde cadena XML
string xmlString = "<Persona><Nombre>Juan</Nombre><Edad>30</Edad></Persona>";
XElement xml = XElement.Parse(xmlString);
Persona persona = xml.Fx.Xml.FromXElement<Persona>();
// persona.Nombre == "Juan", persona.Edad == 30

// Cargar desde archivo y deserializar
XElement archivoXml = XElement.Load("persona.xml");
Persona personaArchivo = archivoXml.Fx.Xml.FromXElement<Persona>();

// Serialización/deserialización de ida y vuelta
var original = new Persona { Nombre = "Alicia", Edad = 25 };
XElement serializado = original.Fx.Xml.ToXElement();
Persona restaurada = serializado.Fx.Xml.FromXElement<Persona>();
// restaurada es equivalente a original
